 h+='<div class="kpis k4">'+stat('Team utilization',tu,'%',badge(band(tu)[0],band(tu)[1]))+stat('Overloaded',over.length,'/ '+ms.length,over.map(function(x){return x.p.name.split(' ')[0]+' '+x.m.util+'%'}).join(', ')||'Nobody')+stat('Under-utilized',under.length,'/ '+(ms.length-onb.length),under.map(function(x){return x.p.name.split(' ')[0]+' '+x.m.util+'%'}).join(', ')||'Nobody')+stat('Stale issues',st,'/ '+op+' open',badge(st/op>0.3?'danger':'accent','Stale')+' '+Math.round(st/op*100)+'% of open work')+'</div>';
