 ms.forEach(function(x){var p=x.p;hm+='<div class="pl-heat" style="'+cols+';cursor:pointer" data-person="'+p.id+'"><span class="row" style="flex-wrap:nowrap"><span class="pl-avatar">'+p.ini+'</span>'+esc(p.name)+'</span>'+ws.map(function(s){if(JOINED[p.id]&&s<JOINED[p.id])return '<span class="pl-heat-cell u0">—</span>';if(p.leave.indexOf(s)>=0)return '<span class="pl-heat-cell u0">Leave</span>';var vv=visitOn(p.id,s);if(vv)return '<span class="pl-heat-cell uv" title="Customer visit · '+esc(vv.customer)+'">Visit</span>';if(onboarding(p.id))return '<span class="pl-heat-cell u1">Training</span>';var v=s<TODAY?(p.logged[s]||0)/S.rules.focus*100:x.m.util;v=Math.round(v);var c=v<S.rules.under?'u1':v<S.rules.healthy?'u2':v<=100?'u3':v<=S.rules.over?'u4':'u5';return '<span class="pl-heat-cell '+c+'" title="'+(s<TODAY?'Logged':'Planned')+'">'+v+'%</span>'}).join('')+'<span class="pl-mono" style="text-align:right">'+(onboarding(p.id)?'—':x.m.util+'%')+'</span></div>'});
 hm+='</div></div><div class="row pl-caption" style="margin-top:12px;gap:14px">'+[['u1','Under <'+S.rules.under+'%'],['u2','Healthy'],['u3','At capacity ≤100%'],['u4','Over ≤'+S.rules.over+'%'],['u5','Critical'],['uv','Customer visit'],['u0','Leave']].map(function(l){return '<span class="row" style="gap:6px"><span class="pl-heat-cell '+l[0]+'" style="width:26px;height:14px"></span>'+l[1]+'</span>'}).join('')+'</div>';
