 h+=card('Monthly effort & extra-mile points','',rg('dayHours','Hours per day','Converts logged hours into days worked',6,9,0.5,' h')+rg('unplannedAlert','Unplanned alert at','Share of logged time that triggers a planning signal',10,60,5,'%')+rg('midsprint','Added mid-sprint (done)','Points per item',0,3,0.5,'',S.rules.pts)+rg('incident','Incident / hotfix','Points per item',0,4,0.5,'',S.rules.pts)+rg('takeover','Took over / helped','Points per item',0,3,0.5,'',S.rules.pts)+rg('untracked','Untracked useful work','Points per item',0,3,0.5,'',S.rules.pts)+rg('reviews','Reviews for others','Points per 5 reviews',0,2,0.5,'',S.rules.pts)+rg('support','Extra support ticket (resolved)','Points per ticket',0,3,0.5,'',S.rules.pts)+rg('proactivefix','Proactive fix of someone else’s bug','Points per bug',0,3,0.5,'',S.rules.pts)+rg('monthCap','Monthly cap','Max points per person per month',2,12,1,'')+rg('bonusPerPoint','Culture bonus per point','Added to each credited value (split across values)',0,0.2,0.01,'')+rg('bonusCap','Max bonus per value','Per quarter',0,1,0.05,''),'Points count only after manager confirmation · capped so extra hours are never the goal');
