 var b=aprBand(a.score),i=R.bands.indexOf(b),top=i===0?5:R.bands[i-1].min,frac=Math.max(0,Math.min(1,(a.score-b.min)/(top-b.min)));
 var pct=Math.min(R.max,Math.round((b.lo+(b.hi-b.lo)*frac)*2)/2),m=monthsBetween(JOINED[p.id]||'2025-01-01','2026-09-30'),elig=m>=R.minMonths;
