function addDays(s,n){var x=d(s);x.setDate(x.getDate()+n);return iso(x)}
function trCycle(a,cp){var id='ct-'+a.id+'-'+cp;var c=cyc(id);if(!c){c={id:id,kind:'training',name:person(a.pid).name.split(' ')[0]+' · Day '+cp+' checkpoint',q:'',status:'Training',due:addDays(a.start,cp),dept:'',groups:{self:1,manager:1,peer:[1,3],cross:[0,2]},anonMin:1,w:{manager:50,peer:30,cross:0,self:20}};CYCLES.push(c)}return c}
function trRequest(a,cp,notifyNow){var c=trCycle(a,cp),su=userOfPerson(a.pid);if(reqsFor(c.id,a.pid).length)return 0;var n=0;
 [[su.id,'self'],[su.mgr,'manager'],[a.mentor,'peer']].forEach(function(x){if(!x[0])return;var r=mkReq(c.id,a.pid,x[0],x[1],'Approved','Training plan');r.label='Day '+cp+' checkpoint';if(notifyNow)notify(r,'request');n++});return n}
