function trProg(a){var req=a.plan.modules;if(!req.length)return 0;return req.filter(function(m){return a.done[m.id]}).length/req.length}
function trOverdue(a){return a.plan.modules.filter(function(m){return !a.done[m.id]&&addDays(a.start,m.week*7)<TODAY})}
function trNextCp(a){var cs=a.plan.checkpoints.map(function(cp){var c=cyc('ct-'+a.id+'-'+cp),rs=c?reqsFor(c.id,a.pid):[];var st=!rs.length?(addDays(a.start,cp)<=addDays(TODAY,7)?'Due':'Scheduled'):(rs.every(function(r){return r.status==='Submitted'})?'Completed':'Requested');return {cp:cp,date:addDays(a.start,cp),c:c,rs:rs,st:st}});return cs}
function trFor(pid){return TASSIGN.filter(function(a){return a.pid===pid})}
function isOnbPlan(tp){return tp.id==='tp1'||tp.id==='tp2'||tp.onboarding}
function trSuggest(p){var cv=cult(p),low=VALUES.map(function(v,i){return [v,cv[i]]}).sort(function(a,b){return a[1]-b[1]}).slice(0,3).map(function(x){return x[0]});
 return TPLANS.filter(function(tp){return !isOnbPlan(tp)&&tp.targets.some(function(t){return low.indexOf(t)>=0})&&!trFor(p.id).some(function(a){return a.plan.id===tp.id&&a.status!=='Completed'})}).map(function(tp){return {tp:tp,why:tp.targets.filter(function(t){return low.indexOf(t)>=0})}})}
function isNewJoiner(pid){return JOINED[pid]&&monthsBetween(JOINED[pid],TODAY)<3}
