function trLibrary(){return '<div class="row" style="justify-content:flex-end"><button class="pl-btn pl-btn-primary" data-act="trnew">New plan</button></div><div class="g2">'+TPLANS.map(function(tp){var used=TASSIGN.filter(function(a){return a.plan.id===tp.id}).length,hrs=tp.modules.reduce(function(s,m){return s+(+m.hours||0)},0);
 return card(esc(tp.name),'<div class="xact"><button class="pl-btn pl-btn-sm" data-act="tredit" data-t="'+tp.id+'">Edit</button><button class="pl-btn pl-btn-sm" data-act="trdup" data-t="'+tp.id+'">Duplicate</button><button class="pl-btn pl-btn-sm pl-btn-danger" data-act="trdel" data-t="'+tp.id+'">Delete</button></div>','<div class="pl-caption">'+esc(tp.desc)+'</div><div class="row" style="margin:10px 0">'+badge('brand',tp.weeks+' weeks')+badge('',tp.modules.length+' modules · '+hrs+' h')+badge('info','Checkpoints day '+tp.checkpoints.join(', '))+badge('ok',(tp.cadence||'Weekly')+' check-ins')+'</div><div class="row" style="gap:4px">'+tp.targets.map(function(t){return badge('ok',t)}).join('')+'</div><div class="row" style="margin-top:12px"><span class="pl-caption">Used by '+used+' '+(used===1?'person':'people')+'</span><span class="sp"></span><button class="pl-btn pl-btn-sm pl-btn-primary" data-act="trassign" data-plan="'+tp.id+'">Assign</button></div>',esc(tp.forRole))}).join('')+'</div>'}
function trDetail(aid){var a=TASSIGN.filter(function(x){return x.id===aid})[0];if(!a){S.trainView=null;return trLibrary()}var p=person(a.pid),pr=trProg(a),mgr=can('training.manage'),weeks={};a.plan.modules.forEach(function(m){(weeks[m.week]=weeks[m.week]||[]).push(m)});
 var h='<div class="hdr"><button class="pl-btn" data-act="trback">← Back</button><div class="who"><div class="pl-eyebrow">Training plan</div><h1>'+esc(p.name)+' · '+esc(a.plan.name)+'</h1><div class="pl-caption">Mentor '+esc((U(a.mentor)||{name:'—'}).name)+' · started '+fmtDate(a.start)+' · ends '+fmtDate(addDays(a.start,a.plan.weeks*7))+'</div></div>'+(mgr?'<div class="xact"><button class="pl-btn" data-act="traedit" data-a="'+a.id+'">Edit assignment</button>'+(a.status==='Active'?'<button class="pl-btn" data-act="trstatus" data-a="'+a.id+'" data-s="Paused">Pause</button><button class="pl-btn pl-btn-primary" data-act="trstatus" data-a="'+a.id+'" data-s="Completed">Mark complete</button>':'<button class="pl-btn" data-act="trstatus" data-a="'+a.id+'" data-s="Active">Resume</button>')+'<button class="pl-btn pl-btn-danger" data-act="traremove" data-a="'+a.id+'">Remove</button></div>':'')+'</div>';
 h+='<div class="kpis k4">'+stat('Progress',Math.round(pr*100),'%',Object.keys(a.done).length+' of '+a.plan.modules.length+' modules')+stat('Overdue',trOverdue(a).length,'','modules past their week')+stat('Hours planned',a.plan.modules.reduce(function(s,m){return s+(+m.hours||0)},0),' h','')+stat('Status',esc(a.status),'',a.plan.targets.join(', '))+'</div>';
 h+='<div class="g2">'+card(cadOf(a)+' progress check-ins',badge('',ciStats(a).v+'/'+ciStats(a).total+' verified')+(ciStats(a).s?badge('info',ciStats(a).s+' to review'):''),checkinList(a,a.pid===me().pid),'Verify each update or send it back with feedback')+feedbackCard(a,'Feedback given')+'</div>';
 h+='<div class="g21">'+card('Modules','<span class="pl-caption">'+(mgr?'Manager and mentor can tick too':'')+'</span>',Object.keys(weeks).sort(function(x,y){return x-y}).map(function(w){return '<div class="xgroup">Week '+w+'</div>'+weeks[w].map(function(m){return modRow(a,m,true)}).join('')}).join(''))+card('Checkpoint reviews','',cpRows(a,mgr),'Same review form and results view as 360° feedback')+'</div>';
 return h}
function planForm(tp){var isNew=!tp;tp=tp?JSON.parse(JSON.stringify(tp)):{name:'',forRole:'',weeks:4,desc:'',targets:[],checkpoints:[14,28],modules:[trM('','Course',1,2,'')]};S.planDraft=tp;S.planDraft.__new=isNew;renderPlanForm()}
function renderPlanForm(){var tp=S.planDraft;
 modal('<h2 class="pl-h2">'+(tp.__new?'New training plan':'Edit training plan')+'</h2><div class="g2" style="gap:10px"><label class="f">Plan name *<input class="inp" id="pf-name" value="'+esc(tp.name)+'"></label><label class="f">For<input class="inp" id="pf-for" value="'+esc(tp.forRole)+'" placeholder="e.g. Trainee / new Software Engineer"></label></div>'+
  '<div class="g2" style="gap:10px"><label class="f">Duration (weeks) *<input class="inp" id="pf-weeks" type="number" min="1" max="52" value="'+tp.weeks+'"></label><label class="f">Progress check-in<select class="sel" id="pf-cad">'+CADENCES.map(function(c){return '<option'+((tp.cadence||'Weekly')===c?' selected':'')+'>'+c+'</option>'}).join('')+'</select></label><label class="f">Checkpoint days<input class="inp" id="pf-cps" value="'+tp.checkpoints.join(', ')+'" placeholder="14, 30, 60, 90"></label><label class="f">Assessment after the period<select class="sel" id="pf-at">'+ASSESS_TYPES.map(function(x){return '<option'+(tp.assessType===x?' selected':'')+'>'+x+'</option>'}).join('')+'</select></label><label class="f">Pass mark (%)<input class="inp" id="pf-pass" type="number" min="1" max="100" value="'+(tp.passMark||S.rules.trPass)+'"></label><label class="f">Description<input class="inp" id="pf-desc" value="'+esc(tp.desc)+'"></label></div>'+
  '<div class="pl-eyebrow">Culture values it builds (used for suggestions)</div><div class="row" style="gap:6px 14px">'+VALUES.map(function(v){return '<label class="row" style="font-size:13px;gap:4px"><input type="checkbox" class="pf-t" value="'+esc(v)+'"'+(tp.targets.indexOf(v)>=0?' checked':'')+'>'+esc(v)+'</label>'}).join('')+'</div>'+
  '<div class="pl-eyebrow">Modules *</div><div id="pf-mods" style="display:flex;flex-direction:column;gap:8px;max-height:280px;overflow:auto">'+tp.modules.map(function(m,i){return '<div class="pfrow"><label class="f">Title<input class="inp pm-t" value="'+esc(m.title)+'"></label><label class="f">Type<select class="sel pm-y">'+MTYPES.map(function(t){return '<option'+(m.type===t?' selected':'')+'>'+t+'</option>'}).join('')+'</select></label><label class="f">Week<input class="inp pm-w" type="number" min="1" value="'+m.week+'"></label><label class="f">Hours<input class="inp pm-h" type="number" min="0" step="0.5" value="'+m.hours+'"></label><label class="f">Resource / link<input class="inp pm-r" value="'+esc(m.res)+'"></label><button class="x" data-act="pmdel" data-i="'+i+'" aria-label="Remove module"'+(tp.modules.length<2?' disabled':'')+'>×</button></div>'}).join('')+'</div><button class="pl-btn pl-btn-sm" data-act="pmadd" style="width:max-content">+ Add module</button><div id="pf-e" class="pl-caption" style="color:var(--danger-ink)"></div><div class="row"><span class="sp"></span><button class="pl-btn" data-act="cancel">Cancel</button><button class="pl-btn pl-btn-primary" data-act="pfsave">'+(tp.__new?'Create plan':'Save plan')+'</button></div>');
 $('#modal .box').style.width='min(900px,96vw)'}
function readPlanForm(){var tp=S.planDraft;tp.name=$('#pf-name').value.trim();tp.forRole=$('#pf-for').value.trim();tp.weeks=+$('#pf-weeks').value;tp.desc=$('#pf-desc').value.trim();tp.cadence=$('#pf-cad').value;tp.passMark=+$('#pf-pass').value||70;tp.assessType=$('#pf-at').value;tp.checkpoints=$('#pf-cps').value.split(/[,\s]+/).filter(Boolean).map(Number).filter(function(x){return x>0}).sort(function(a,b){return a-b});
 tp.targets=[].map.call(document.querySelectorAll('.pf-t:checked'),function(c){return c.value});
 var rows=[].slice.call(document.querySelectorAll('#pf-mods .pfrow'));tp.modules=rows.map(function(r,i){return {id:(tp.modules[i]&&tp.modules[i].id)||trM('','',1,0).id,title:r.querySelector('.pm-t').value.trim(),type:r.querySelector('.pm-y').value,week:+r.querySelector('.pm-w').value,hours:+r.querySelector('.pm-h').value,res:r.querySelector('.pm-r').value.trim()}})}
function assignTrainModal(pid,planId){var ps=visiblePeople().slice().sort(function(a,b){return (isNewJoiner(b.id)?1:0)-(isNewJoiner(a.id)?1:0)}),mentors=USERS.filter(function(u){return u.status==='Active'&&u.pid});
 modal('<h2 class="pl-h2">Assign training plan</h2><div class="g2" style="gap:12px;align-items:start"><div><label class="f">Plan *<select class="sel" id="ta-plan"><option value="">Select a plan…</option>'+TPLANS.map(function(tp){return '<option value="'+tp.id+'"'+(tp.id===planId?' selected':'')+'>'+esc(tp.name)+' · '+tp.weeks+' wk</option>'}).join('')+'</select></label><label class="f" style="margin-top:10px">Mentor *<select class="sel" id="ta-mentor"><option value="">Select a mentor…</option>'+mentors.map(function(u){return '<option value="'+u.id+'">'+esc(u.name)+' · '+esc(u.title||(person(u.pid)||{}).role||'')+' · mentoring '+(typeof mentees==='function'?mentees(u.id).filter(trActiveStage).length:0)+'</option>'}).join('')+'</select></label><label class="f" style="margin-top:10px">Progress check-in<select class="sel" id="ta-cad"><option value="">Use plan default</option>'+CADENCES.map(function(c){return '<option>'+c+'</option>'}).join('')+'</select></label><label class="f" style="margin-top:10px">Start date *<input class="inp" id="ta-start" type="date" value="'+TODAY+'"></label><label class="row" style="font-size:13px;margin-top:10px"><input type="checkbox" id="ta-cp" checked> Schedule checkpoint reviews (self, manager, mentor)</label>'+(typeof MEETS!=='undefined'?'<label class="f" style="margin-top:10px">Mentor meetings (day-to-day talks)<select class="sel" id="ta-meet"><option value="">Plan default</option>'+MEETS.map(function(m){return '<option>'+m+'</option>'}).join('')+'</select></label>':'')+'</div>'+
  '<div><div class="pl-eyebrow">People *</div><div style="max-height:320px;overflow:auto;margin-top:6px">'+ps.map(function(p){var has=trFor(p.id).filter(function(a){return a.status!=='Completed'}).map(function(a){return a.plan.name});return '<label class="row" style="padding:4px 0;font-size:14px;flex-wrap:nowrap"><input type="checkbox" class="ta-p" value="'+p.id+'"'+(p.id===pid?' checked':'')+'><span class="pl-avatar">'+p.ini+'</span><span>'+esc(p.name)+(isNewJoiner(p.id)?' '+badge('info','New joiner'):'')+(has.length?'<span class="pl-caption" style="display:block">has: '+esc(has.join(', '))+'</span>':'')+'</span></label>'}).join('')+'</div></div></div><div id="ta-e" class="pl-caption" style="color:var(--danger-ink)"></div><div class="row"><span class="sp"></span><button class="pl-btn" data-act="cancel">Cancel</button><button class="pl-btn pl-btn-primary" data-act="tasave">Assign & notify</button></div>');
 $('#modal .box').style.width='min(820px,96vw)'}
function trNotify(uid,text){NOTIFS.unshift({id:'n'+(NOTIFS.length+1)+'-t'+Math.random().toString(36).slice(2,6),uid:uid,req:null,go:'training',kind:'training',read:false,at:TODAY,text:text})}

/* ================= TRAINING CHECK-INS (daily / weekly / monthly) + FEEDBACK ================= */
var CADENCES=['Daily','Weekly','Monthly'];
TPLANS.forEach(function(tp){tp.cadence=tp.id==='tp3'?'Daily':'Weekly'});
TASSIGN.forEach(function(a){a.plan.cadence=a.plan.id==='tp3'?'Daily':'Weekly';a.updates=a.updates||[]});
function cadOf(a){return a.cadence||a.plan.cadence||'Weekly'}
function mondayOf(s){var x=d(s),w=(x.getDay()+6)%7;x.setDate(x.getDate()-w);return iso(x)}
function planEnd(a){return addDays(a.start,a.plan.weeks*7-1)}
function periods(a){var cad=cadOf(a),end=planEnd(a)<TODAY?planEnd(a):TODAY,out=[];
 if(cad==='Daily'){workBetween(a.start,end).forEach(function(s){out.push({key:s,label:fmtDay(s),from:s,to:s})})}
 else if(cad==='Weekly'){var m=mondayOf(a.start);while(m<=end){var f=m<a.start?a.start:m;out.push({key:m,label:'Week of '+fmtDate(m),from:f,to:addDays(m,4)});m=addDays(m,7)}}
 else{var x=d(a.start);x.setDate(1);while(iso(x)<=end){var k=iso(x).slice(0,7),ld=new Date(x.getFullYear(),x.getMonth()+1,0);out.push({key:k,label:x.toLocaleDateString('en-GB',{month:'long',year:'numeric'}),from:iso(x)<a.start?a.start:iso(x),to:iso(ld)});x.setMonth(x.getMonth()+1)}}
 out.forEach(function(p){p.cur=p.to>=TODAY||(cad==='Daily'&&p.key===TODAY)});return out.reverse()}
function updOf(a,key){return (a.updates||[]).filter(function(u){return u.period===key})[0]}
function pStat(a,p){var u=updOf(a,p.key);if(u)return u.status;return p.cur?'Due':'Missed'}
var PSTONE={'Verified':'ok','Submitted':'info','Needs work':'accent','Missed':'danger','Due':''};
function ciStats(a){var ps=periods(a),v=0,s=0,n=0,m=0;ps.forEach(function(p){var st=pStat(a,p);if(st==='Verified')v++;else if(st==='Submitted')s++;else if(st==='Needs work')n++;else if(st==='Missed')m++});return {ps:ps,v:v,s:s,n:n,m:m,total:ps.length}}
function isMentor(a){return a.mentor===me().id}
function canVerify(a){return isMentor(a)||can('training.manage')}
function modsIn(a,p){return a.plan.modules.filter(function(m){var dn=a.done[m.id];return dn&&dn.at>=p.from&&dn.at<=p.to})}
function checkinList(a,forTrainee){var ps=periods(a),show=cadOf(a)==='Daily'?ps.slice(0,10):ps;
 return '<div class="xlist">'+show.map(function(p){var u=updOf(a,p.key),st=pStat(a,p),mods=modsIn(a,p);
  var right=badge(PSTONE[st],st)+(forTrainee&&!u&&(p.cur||st==='Missed')&&a.status==='Active'?'<button class="pl-btn pl-btn-sm pl-btn-primary" data-act="ciopen" data-a="'+a.id+'" data-k="'+p.key+'">'+(st==='Missed'?'Submit late':'Submit update')+'</button>':'')+(forTrainee&&u&&u.status==='Needs work'&&a.status==='Active'?'<button class="pl-btn pl-btn-sm" data-act="ciopen" data-a="'+a.id+'" data-k="'+p.key+'">Update & resend</button>':'')+(!forTrainee&&u&&u.status==='Submitted'&&canVerify(a)?'<button class="pl-btn pl-btn-sm pl-btn-primary" data-act="civerify" data-a="'+a.id+'" data-k="'+p.key+'">Review</button>':'');
  return '<div class="xitem" style="grid-template-columns:minmax(0,1fr) auto;cursor:default"><div><b>'+esc(p.label)+'</b> <span class="pl-caption">'+fmtDate(p.from)+(p.to!==p.from?' – '+fmtDate(p.to):'')+'</span>'+
   (u?'<div style="margin-top:4px">'+esc(u.done)+'</div><div class="pl-caption">'+u.hours+' h · confidence '+u.conf+'/5'+(u.blockers?' · blocker: '+esc(u.blockers):'')+(u.next?' · next: '+esc(u.next):'')+'</div>':'<div class="pl-caption">'+(st==='Due'?'Update due by '+fmtDate(p.to):'No update was submitted')+'</div>')+
   (mods.length?'<div class="pl-caption">Modules finished: '+mods.map(function(m){return esc(m.title)}).join(' · ')+'</div>':'')+
   (u&&u.comment?'<div class="ev-card" style="margin-top:6px"><div class="row"><b>'+esc(u.reviewer)+'</b>'+badge(u.revRole==='Mentor'?'ok':'brand',u.revRole)+'<span class="sp"></span><span class="pl-caption">'+fmtDate(u.verifiedAt)+'</span></div><div>'+esc(u.comment)+'</div></div>':'')+
   '</div><div class="xa"><div class="xact">'+right+'</div></div></div>'}).join('')+(ps.length>show.length?'<div class="pl-caption" style="padding:8px 12px">Showing the last '+show.length+' of '+ps.length+' days</div>':'')+'</div>'}
function feedbackFor(a){var out=[],su=userOfPerson(a.pid);
 (a.updates||[]).forEach(function(u){if(u.comment)out.push({at:u.verifiedAt,who:u.reviewer,role:u.revRole,kind:u.status==='Verified'?'Check-in verified':'Needs work',tone:u.status==='Verified'?'ok':'accent',text:u.comment,ctx:u.periodLabel})});
 CYCLES.filter(function(c){return c.kind==='training'&&c.id.indexOf('ct-'+a.id+'-')===0}).forEach(function(c){reqsFor(c.id,a.pid).forEach(function(r){if(r.status!=='Submitted'||r.group==='self')return;var ru=U(r.reviewer);var sc=r.answers.scores.filter(function(x){return x!==null}),avg=sc.length?sc.reduce(function(s,x){return s+x},0)/sc.length:null;
  out.push({at:r.at||c.due,who:ru?ru.name:'—',role:r.group==='manager'?'Manager':'Mentor',kind:(r.label||c.name)+' review'+(avg?' · avg '+avg.toFixed(1)+'/5':''),tone:'brand',text:'Keep: '+r.answers.keep+'  ·  Start: '+r.answers.start,ctx:''})})});
 return out.sort(function(x,y){return x.at<y.at?1:-1})}
function feedbackCard(a,title){var fb=feedbackFor(a);return card(title||'Feedback from mentor & manager','',fb.length?'<div class="xlist">'+fb.map(function(f){return '<div class="ev-card" style="margin-bottom:8px"><div class="row" style="gap:6px"><b>'+esc(f.who)+'</b>'+badge(f.role==='Mentor'?'ok':'brand',f.role)+badge(f.tone,f.kind)+'<span class="sp"></span><span class="pl-caption">'+fmtDate(f.at)+'</span></div>'+(f.ctx?'<div class="pl-caption">'+esc(f.ctx)+'</div>':'')+'<div style="margin-top:4px">'+esc(f.text)+'</div></div>'}).join('')+'</div>':'<div class="empty">No feedback yet. It appears here when your mentor or manager reviews a check-in or a checkpoint.</div>','From check-in reviews and checkpoint reviews · named, visible to you')}
function ciModal(aid,key){var a=TASSIGN.filter(function(x){return x.id===aid})[0],p=periods(a).filter(function(x){return x.key===key})[0],u=updOf(a,key)||{},mods=modsIn(a,p);
 modal('<h2 class="pl-h2">Progress update · '+esc(p.label)+'</h2><div class="pl-caption">'+esc(a.plan.name)+' · '+cadOf(a).toLowerCase()+' check-in · reviewed by your mentor '+esc((U(a.mentor)||{name:'—'}).name)+'</div>'+(u.comment?'<div class="pl-alert">'+badge('accent','Needs work')+'<span><b>'+esc(u.reviewer)+':</b> '+esc(u.comment)+'</span><span></span></div>':'')+
  (mods.length?'<div class="note">Modules ticked in this period: '+mods.map(function(m){return esc(m.title)}).join(' · ')+'</div>':'')+
  '<label class="f">What did you complete? *<textarea class="inp" id="ci-done" rows="3" placeholder="Modules, tasks, what you learned">'+esc(u.done||'')+'</textarea></label><div class="g3" style="gap:10px"><label class="f">Hours spent *<input class="inp" id="ci-h" type="number" min="0.5" step="0.5" value="'+(u.hours||'')+'"></label><label class="f">Confidence (1–5)<select class="sel" id="ci-c">'+[1,2,3,4,5].map(function(n){return '<option'+((u.conf||3)===n?' selected':'')+'>'+n+'</option>'}).join('')+'</select></label><label class="f">Blockers<input class="inp" id="ci-b" value="'+esc(u.blockers||'')+'" placeholder="None"></label></div><label class="f">Plan for next '+(cadOf(a)==='Daily'?'day':cadOf(a)==='Weekly'?'week':'month')+'<input class="inp" id="ci-n" value="'+esc(u.next||'')+'"></label><div id="ci-e" class="pl-caption" style="color:var(--danger-ink)"></div><div class="row"><span class="sp"></span><button class="pl-btn" data-act="cancel">Cancel</button><button class="pl-btn pl-btn-primary" data-act="cisave" data-a="'+a.id+'" data-k="'+key+'">Submit for review</button></div>');
 $('#modal .box').style.width='min(640px,94vw)'}
function verifyModal(aid,key){var a=TASSIGN.filter(function(x){return x.id===aid})[0],p=periods(a).filter(function(x){return x.key===key})[0],u=updOf(a,key),mods=modsIn(a,p);
 modal('<h2 class="pl-h2">Review check-in · '+esc(person(a.pid).name)+'</h2><div class="pl-caption">'+esc(p.label)+' · '+esc(a.plan.name)+'</div><div class="ev-card"><div><b>Completed:</b> '+esc(u.done)+'</div><div class="pl-caption">'+u.hours+' h · confidence '+u.conf+'/5'+(u.blockers?' · blocker: '+esc(u.blockers):'')+(u.next?' · next: '+esc(u.next):'')+'</div>'+(mods.length?'<div class="pl-caption">Modules ticked: '+mods.map(function(m){return esc(m.title)}).join(' · ')+'</div>':'<div class="pl-caption">No modules ticked in this period</div>')+'</div><label class="f">Feedback to '+esc(person(a.pid).name.split(' ')[0])+' (required for “Needs work”)<textarea class="inp" id="vf-c" rows="3" placeholder="What went well, what to change"></textarea></label><div id="vf-e" class="pl-caption" style="color:var(--danger-ink)"></div><div class="row"><span class="sp"></span><button class="pl-btn" data-act="cancel">Cancel</button><button class="pl-btn" data-act="vfsave" data-a="'+a.id+'" data-k="'+key+'" data-s="Needs work">Needs work</button><button class="pl-btn pl-btn-primary" data-act="vfsave" data-a="'+a.id+'" data-k="'+key+'" data-s="Verified">✓ Verify</button></div>');
 $('#modal .box').style.width='min(620px,94vw)'}
function mentoringCard(){var ms=TASSIGN.filter(function(a){return a.mentor===me().id&&a.status==='Active'});if(!ms.length)return '';
 return card('People I mentor','','<div class="xlist">'+ms.map(function(a){var cs=ciStats(a);return '<div class="xitem" style="grid-template-columns:minmax(0,1fr) auto;cursor:default"><div><b>'+esc(person(a.pid).name)+'</b> <span class="pl-caption">'+esc(a.plan.name)+' · '+cadOf(a).toLowerCase()+' check-ins</span><div style="margin-top:6px;max-width:320px">'+meter(Math.round(trProg(a)*100),'info',100)+'</div></div><div class="xa"><div class="xact">'+(cs.s?badge('info',cs.s+' to review'):badge('ok','Up to date'))+'<button class="pl-btn pl-btn-sm pl-btn-primary" data-act="trview" data-a="'+a.id+'">Open</button></div></div></div>'}).join('')+'</div>','Review their check-ins and tick modules with them')}
/* seed check-ins */
