 cs.push({k:'build',l:'Build / pipeline passed',ok:act&&pr.build?null:pr.build,why:'Merged with a failed or skipped build'});
 if(R.prThreads)cs.push({k:'threads',l:'Blocking threads resolved before merge',ok:act?null:open===0,why:open+' blocking thread'+(open===1?'':'s')+' still open at merge'});
