function prTabs(){return vCanManage()?'<div class="pl-tabs"><button class="pl-tab'+(S.prTab!=='person'?' is-active':'')+'" data-act="prtab" data-k="team">Team</button><button class="pl-tab'+(S.prTab==='person'?' is-active':'')+'" data-act="prtab" data-k="person">Person</button></div>':''}
