 if(act==='imptplx'){csvDownload(IMPORTERS[el.dataset.type].file,impTemplate(el.dataset.type));return true}
 if(act==='imppaste'){var tx=$('#imp-text').value;if(!tx.trim()){S.imp.err='Paste some CSV text first.';impRender();return true}impLoad(tx,'pasted text');return true}
 if(act==='impback'){S.imp.step='pick';S.imp.err='';impRender();return true}
 if(act==='impmode'){S.imp.mode=el.dataset.m;S.imp.res=IMPORTERS[S.imp.type].check(S.imp.objs,S.imp.mode);impRender();return true}
 if(act==='impgo'){var s=S.imp,I=IMPORTERS[s.type],R=s.res;if(!R.data.length)return true;var out=I.apply(R,s.mode),mode=(I.modes.filter(function(m){return m[0]===s.mode})[0]||I.modes[0])[1];
  var L={id:'il'+Date.now(),type:s.type,file:s.fname,by:me().name,at:nowStamp(),rows:s.objs.length,ok:R.items.filter(function(x){return x.act!=='Skip'}).length,err:R.errors.length,warn:R.warns.length,mode:mode,undo:out.undo,undone:false,msg:out.msg};
  IMPORT_LOG.unshift(L);s.log=L;s.step='done';render();impRender();toast(out.msg);return true}
 if(act==='impundo'){var x=IMPORT_LOG.filter(function(y){return y.id===el.dataset.id})[0];if(!x||!x.undo||x.undone)return true;x.undo();x.undone=true;if(S.imp&&S.imp.log===x)closeModal();render();toast('Import undone · '+x.file);return true}
