function nav(){
 var u=me(),perms=ROLES[u.role].perms,routes=routesFor(u),mm=S.person?metrics(person(S.person)):{stale:[]};
 var pend=EXTRA.filter(function(x){return x.state==='pending'&&inPer(x.date,curPer())&&canSeePerson(x.pid)}).length;
 var rv360=REQS.filter(function(r){return r.reviewer===u.id&&(r.status==='Approved'||r.status==='Draft')&&cyc(r.cycle).status!=='Published'}).length;
 function a(r){return '<a href="javascript:void(0)" role="button" data-go="'+r+'" class="'+(S.route===r?'on':'')+'"><svg viewBox="0 0 24 24">'+ICONS[r]+'</svg>'+PAGES[r][0]+(r==='sprint'&&mm.stale.length?'<span class="cnt">'+mm.stale.length+'</span>':'')+(r==='reviews'&&rv360?'<span class="cnt">'+rv360+'</span>':'')+(r==='effort'&&can('effort.confirm')&&pend?'<span class="cnt">'+pend+'</span>':'')+(r==='visits'&&vTodo()?'<span class="cnt">'+vTodo()+'</span>':'')+(r==='actions'&&typeof actionItems==='function'?(function(){var n=actionItems().filter(function(x){return x.pri===1}).length;return n?'<span class="cnt">'+n+'</span>':''})():'')+(r==='training'&&trTodo()?'<span class="cnt">'+trTodo()+'</span>':'')+'</a>'}
 var sec=[[u.pid?'My work':((can('team.view')||can('all.view'))?'People':'Feedback'),['overview','progress','sprint','prs','effort','quality','visits','attendance','okrs','training','roadmap','culture','reviews']],['Manager',['actions','team','appraisal']],['Administration',['users','imports','roles','integrations','rules']]];
 var h='<div class="logo"><i></i>Pulse</div>';
 sec.forEach(function(g,gi){var rs=g[1].filter(function(r){return routes.indexOf(r)>=0});if(!rs.length)return;if(gi>0||!u.pid)h+='<div class="pl-eyebrow sec">'+g[0]+'</div>';h+=rs.map(a).join('')});
 h+='<div class="foot"><div class="row" style="flex-wrap:nowrap"><span class="pl-avatar">'+u.name.split(' ').map(function(w){return w[0]}).join('').slice(0,2)+'</span><div style="min-width:0"><div style="font-weight:600">'+esc(u.name)+'</div><div class="pl-caption">'+esc(u.role)+'</div></div></div><button class="pl-btn pl-btn-sm" data-act="logout" style="margin-top:10px;width:100%;justify-content:center">Sign out</button><div class="pl-caption" style="margin-top:8px">Prototype · sample data · today Mon 28 Sep 2026</div></div>';
 $('#side').innerHTML=h}
