 if(vp.length>1&&((PERSON_PAGES.indexOf(S.route)>=0&&S.route!=='effort'&&S.route!=='quality')||(S.route==='reviews'&&S.revTab!=='360'&&!S.r360Subject)||(S.route==='quality'&&!(S.qTab==='team'&&(can('team.view')||can('all.view'))))||(S.route==='effort'&&S.effortTab==='person'&&(can('team.view')||can('all.view')))||(S.route==='okrs'&&S.okrScope==='person')||(S.route==='visits'&&S.vTab==='person'&&vCanManage())||(S.route==='prs'&&S.prTab==='person'&&vCanManage())||(S.route==='attendance'&&S.attTab==='person'&&(can('team.view')||can('all.view')))))h+='<select class="sel" id="ppl" aria-label="Person">'+vp.map(function(q){return '<option value="'+q.id+'"'+(q.id===S.person?' selected':'')+'>'+esc(q.name)+(q.id===u.pid?' (me)':'')+'</option>'}).join('')+'</select>';
 var un=unread();h+='<span class="bellwrap"><button class="pl-btn pl-btn-sm bell" data-act="bell" aria-label="Notifications'+(un?', '+un+' unread':'')+'" aria-expanded="'+(S.bellOpen?'true':'false')+'"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 1 0-12 0c0 7-3 9-3 9h18s-3-2-3-9M13.7 21a2 2 0 0 1-3.4 0"/></svg>'+(un?'<span class="bellcnt">'+un+'</span>':'')+'</button>'+(S.bellOpen?bellPanel():'')+'</span><button class="pl-btn pl-btn-sm" data-act="theme" aria-label="Toggle theme">◐</button><button class="pl-btn pl-btn-sm" data-act="logout">Sign out</button>';
