 if(lv)lv.parentNode.removeChild(lv);app.style.display='';
 var u=me(),routes=routesFor(u);S.role=(can('team.view')||can('all.view'))?'manager':'employee';
 var r=S.route;if(REV_ALIAS[r]){S.revTab=REV_ALIAS[r];r='reviews'}if(!PAGES[r])r=routes[0]||'overview';S.route=r;
 var vp=visiblePeople();if(!S.person||!canSeePerson(S.person))S.person=u.pid&&canSeePerson(u.pid)?u.pid:(vp[0]&&vp[0].id)||null;
